package pgstore

import (
	"context"
	"database/sql"
	"path/filepath"
	"testing"

	_ "modernc.org/sqlite"
)

// These tests run Migrate against a SQLite stand-in: live Postgres is
// unavailable in the offline suite, and the stand-in proves the migration's
// idempotence and the tolerated duplicate-column ALTERs on the shared
// dialect. The Postgres-specific facts (BIGINT vs INTEGER, BIGSERIAL) are
// schema text only and change no behavior here; note that the SQLite
// driver does not implement BIGSERIAL auto-increment, so these tests never
// rely on an id being generated by the engine.

// TestMigrateIdempotentOnReopen runs Migrate twice against a fresh stand-in
// database: the second run must be a clean no-op - every CREATE is
// IF NOT EXISTS and both ALTERs tolerate their own duplicates.
func TestMigrateIdempotentOnReopen(t *testing.T) {
	ctx := context.Background()
	path := filepath.Join(t.TempDir(), "slotfared.db")
	s := standinStore(t, path)
	if err := Migrate(ctx, s.db); err != nil {
		t.Fatalf("first Migrate: %v", err)
	}
	if err := Migrate(ctx, s.db); err != nil {
		t.Fatalf("second Migrate must be a no-op: %v", err)
	}
	// The migrated usage table carries both new columns.
	var kindCol, durCol int
	if err := s.db.QueryRow(`SELECT COUNT(*) FROM pragma_table_info('usage') WHERE name = 'kind'`).Scan(&kindCol); err != nil {
		t.Fatalf("pragma_table_info(usage): %v", err)
	}
	if err := s.db.QueryRow(`SELECT COUNT(*) FROM pragma_table_info('usage') WHERE name = 'duration_ms'`).Scan(&durCol); err != nil {
		t.Fatalf("pragma_table_info(usage): %v", err)
	}
	if kindCol != 1 || durCol != 1 {
		t.Errorf("migrated usage table columns = (kind %d, duration_ms %d), want (1, 1)", kindCol, durCol)
	}
	// The migrated funding table carries the swap-leg columns.
	var swapCols int
	if err := s.db.QueryRow(`SELECT COUNT(*) FROM pragma_table_info('funding') WHERE name IN
		('swap_token_in', 'swap_amount_in', 'swap_native')`).Scan(&swapCols); err != nil {
		t.Fatalf("pragma_table_info(funding): %v", err)
	}
	if swapCols != 3 {
		t.Errorf("migrated funding table has %d swap columns, want 3", swapCols)
	}
}

// TestMigrateAddsSwapLegToOldFundingSchema seeds a database with the funding
// table as it existed before the swap leg (no swap_* columns), runs Migrate
// once and checks the three columns land via the tolerated ALTERs, then runs
// it again to prove the ALTERs stay idempotent over an old schema.
func TestMigrateAddsSwapLegToOldFundingSchema(t *testing.T) {
	ctx := context.Background()
	path := filepath.Join(t.TempDir(), "old-funding.db")
	db, err := sql.Open("sqlite", "file:"+path)
	if err != nil {
		t.Fatalf("open sqlite: %v", err)
	}
	oldFunding := `CREATE TABLE funding (
		account_id TEXT NOT NULL,
		chain_key INTEGER NOT NULL,
		deposit_id TEXT NOT NULL,
		source_tx TEXT NOT NULL DEFAULT '',
		source_block INTEGER NOT NULL DEFAULT 0,
		attested_height INTEGER NOT NULL DEFAULT 0,
		credited INTEGER NOT NULL DEFAULT 0,
		token TEXT NOT NULL DEFAULT '',
		usd_micros INTEGER NOT NULL DEFAULT 0,
		started_at TEXT NOT NULL DEFAULT '',
		cc_tx TEXT NOT NULL DEFAULT '',
		cc_block INTEGER NOT NULL DEFAULT 0,
		credits INTEGER NOT NULL DEFAULT 0,
		credited_at TEXT NOT NULL DEFAULT '',
		PRIMARY KEY (account_id, chain_key, deposit_id)
	)`
	if _, err := db.Exec(oldFunding); err != nil {
		t.Fatalf("create old funding schema: %v", err)
	}
	db.Close()

	s := standinStore(t, path)
	if err := Migrate(ctx, s.db); err != nil {
		t.Fatalf("Migrate on old-funding database: %v", err)
	}
	var swapCols int
	if err := s.db.QueryRow(`SELECT COUNT(*) FROM pragma_table_info('funding') WHERE name IN
		('swap_token_in', 'swap_amount_in', 'swap_native')`).Scan(&swapCols); err != nil {
		t.Fatalf("pragma_table_info(funding): %v", err)
	}
	if swapCols != 3 {
		t.Fatalf("columns after Migrate = %d swap columns, want 3", swapCols)
	}
	// Second run over the now-migrated old schema: still a clean no-op.
	if err := Migrate(ctx, s.db); err != nil {
		t.Fatalf("second Migrate on old-funding database: %v", err)
	}
}

// TestMigrateAddsDurationToOldUsageSchema seeds a database with the old
// usage table (no kind, no duration_ms), runs Migrate once and checks the
// column exists with pre-existing rows reading back as NULL, then runs it
// again to prove the tolerated ALTERs stay idempotent over an old schema.
func TestMigrateAddsDurationToOldUsageSchema(t *testing.T) {
	ctx := context.Background()
	path := filepath.Join(t.TempDir(), "old-usage.db")
	db, err := sql.Open("sqlite", "file:"+path)
	if err != nil {
		t.Fatalf("open sqlite: %v", err)
	}
	oldUsage := `CREATE TABLE usage (
		id INTEGER PRIMARY KEY AUTOINCREMENT,
		account_id TEXT NOT NULL,
		key_prefix TEXT NOT NULL,
		ts INTEGER NOT NULL,
		service TEXT NOT NULL,
		model TEXT NOT NULL,
		prompt_tokens INTEGER NOT NULL,
		cached_tokens INTEGER NOT NULL,
		completion_tokens INTEGER NOT NULL,
		credits INTEGER NOT NULL,
		status TEXT NOT NULL
	)`
	if _, err := db.Exec(oldUsage); err != nil {
		t.Fatalf("create old usage schema: %v", err)
	}
	if _, err := db.Exec(`INSERT INTO usage (account_id, key_prefix, ts, service, model, prompt_tokens, cached_tokens, completion_tokens, credits, status) VALUES ('a', 'attk_abcdefg', 0, 'rpc', 'm', 5, 0, 13, 7, 'ok')`); err != nil {
		t.Fatalf("insert old usage row: %v", err)
	}
	db.Close()

	s := standinStore(t, path)
	if err := Migrate(ctx, s.db); err != nil {
		t.Fatalf("Migrate on old-usage database: %v", err)
	}
	var hasKind, hasDur int
	if err := s.db.QueryRow(`SELECT COUNT(*) FROM pragma_table_info('usage') WHERE name = 'kind'`).Scan(&hasKind); err != nil {
		t.Fatalf("pragma_table_info(usage): %v", err)
	}
	if err := s.db.QueryRow(`SELECT COUNT(*) FROM pragma_table_info('usage') WHERE name = 'duration_ms'`).Scan(&hasDur); err != nil {
		t.Fatalf("pragma_table_info(usage): %v", err)
	}
	if hasKind != 1 || hasDur != 1 {
		t.Fatalf("columns after Migrate = (kind %d, duration_ms %d), want (1, 1)", hasKind, hasDur)
	}
	// The pre-existing row reads back with a NULL duration: absent, never
	// fabricated as 0. (The old table's INTEGER PRIMARY KEY gives the row
	// a real id, so the store's scan works on this stand-in.)
	rows, err := s.RecentUsage(ctx, "a", 10, "", false, 0)
	if err != nil || len(rows) != 1 {
		t.Fatalf("RecentUsage on old-usage database: %v, %d rows", err, len(rows))
	}
	if rows[0].DurationMS != nil {
		t.Errorf("pre-existing row duration = %d, want nil (NULL reads back absent)", *rows[0].DurationMS)
	}
	// Second run over the now-migrated old schema: still a clean no-op.
	if err := Migrate(ctx, s.db); err != nil {
		t.Fatalf("second Migrate on old-usage database: %v", err)
	}
}
